advanced_js:
/* Steam achievements: behaves like the PSN trophy overlay.
   Data: steam_data_update (sent by Mycelian about every 15 s; asked for with get_steam_data).
   Change the settings below to tune it; colors, fonts and sizes are in Source Settings. */
var STEAM_SETTINGS = {
    updateIntervalSec: 30,       /* ask Mycelian for fresh data this often (0 = only on change) */
    autoHide: true,              /* fade out while no game is running */
    autoHideDelaySec: 30,        /* ...after this many seconds */
    showChanges: true,           /* "+1 achievement" pop-up when you unlock one */
    changeDurationSec: 3,        /* how long the pop-up stays */
    enableAnimations: true,      /* small scale flash when the numbers change */
    animationSec: 0.3,
    showPerfectBadge: true,      /* gold badge once every achievement is unlocked */
    shimmerSec: 2,               /* progress bar shine speed (0 = off) */
    defaultGameName: 'No Game Detected',
    defaultGameIcon: '/assets/default_assets/images/notingame.png',
    notConnectedIcon: '/assets/default_assets/images/notconnected.png',
    messageFormat: '{earned} out of {total} achievements',
    noAchievementsText: 'No achievements in this game',
    privateText: 'Achievements are private',
    levelFormat: 'Steam Level: {level}'
};

(function () {
    var S = STEAM_SETTINGS;
    var $ = function (id) { return document.getElementById(id); };
    var root = $('game_icon') ? $('game_icon').parentElement : document.body;
    var state = { appid: null, earned: 0, total: 0, gameName: '', icon: '', hidden: false };
    var hideTimer = null;
    var changeTimer = null;
    var lastPaint = 0;
    var painted = false;
    var CACHE_KEY = 'mycelian_steam_achievements_state';

    var css = document.createElement('style');
    css.textContent = [
        '.stm-root{transition:opacity ' + S.animationSec + 's ease,transform ' + S.animationSec + 's ease;transform-origin:center}',
        '.stm-root.stm-updating{opacity:.8;transform:scale(.98)}',
        '.stm-root.stm-hidden{opacity:0;visibility:hidden;transform:scale(.8)}',
        '#game_icon{object-fit:cover;transition:transform ' + S.animationSec + 's ease}',
        '#progress .spore-progress-fill{position:relative;overflow:hidden}',
        S.shimmerSec > 0 ? '#progress .spore-progress-fill::after{content:"";position:absolute;top:0;left:-100%;width:100%;height:100%;' +
            'background:linear-gradient(90deg,transparent,rgba(255,255,255,.3),transparent);animation:stmShimmer ' + S.shimmerSec + 's infinite}' : '',
        '@keyframes stmShimmer{0%{left:-100%}100%{left:100%}}',
        '#perfect_badge{animation:stmGlow 1.5s infinite alternate}',
        '@keyframes stmGlow{0%{filter:brightness(1.2) drop-shadow(0 0 5px #ffd700)}100%{filter:brightness(1.2) drop-shadow(0 0 15px #ffd700)}}',
        '#ach_change{transition:opacity ' + S.changeDurationSec + 's ease,transform ' + S.changeDurationSec + 's ease;opacity:0;pointer-events:none}',
        '#ach_change.stm-show{opacity:1;transform:translateY(-30px)}'
    ].join('\n');
    document.head.appendChild(css);
    if (root) { root.classList.add('stm-root'); }

    function setText(id, text) {
        if (typeof sporeSetText === 'function') { sporeSetText(id, text); return; }
        var el = $(id);
        if (el) { el.textContent = text; }
    }
    function show(id, on) {
        var el = $(id);
        if (!el) { return; }
        if (on) {
            if (typeof sporeShow === 'function') { sporeShow(id); } else { el.style.display = ''; }
        } else if (typeof sporeHide === 'function') {
            sporeHide(id);
        } else {
            el.style.display = 'none';
        }
    }
    function fmt(template, values) {
        return String(template).replace(/\{(\w+)\}/g, function (m, k) { return values[k] != null ? values[k] : m; });
    }
    function setProgress(earned, total) {
        var pct = total > 0 ? Math.round(earned / total * 100) : 0;
        var bars = window.__sporeProgressBars || [];
        var spec = null;
        for (var i = 0; i < bars.length; i++) { if (bars[i].elementId === 'progress') { spec = bars[i]; } }
        if (spec && typeof sporeUpdateProgressBars === 'function') {
            spec.override_value = pct;
            spec.override_max = 100;
            sporeUpdateProgressBars(null);
        } else {
            var fill = document.querySelector('#progress .spore-progress-fill');
            if (fill) { fill.style.width = pct + '%'; }
        }
        setText('progress_label', pct + '%');
    }
    function setIcon(urls) {
        var img = $('game_icon');
        if (!img) { return; }
        var list = urls.filter(Boolean);
        var key = list.join('|');
        if (img.getAttribute('data-stm-src') === key) { return; }
        img.setAttribute('data-stm-src', key);
        var i = 0;
        img.onerror = function () { i += 1; if (i < list.length) { img.src = list[i]; } else { img.onerror = null; } };
        img.src = list[0] || S.defaultGameIcon;
    }
    function showChange(n) {
        if (!S.showChanges || n <= 0) { return; }
        var el = $('ach_change');
        if (!el) { return; }
        setText('ach_change', '+' + n + ' achievement' + (n > 1 ? 's' : ''));
        show('ach_change', true);
        el.classList.remove('stm-show');
        void el.offsetWidth;
        el.classList.add('stm-show');
        clearTimeout(changeTimer);
        changeTimer = setTimeout(function () {
            el.classList.remove('stm-show');
            setTimeout(function () { show('ach_change', false); }, S.changeDurationSec * 1000);
        }, S.changeDurationSec * 1000);
    }
    function setHidden(hidden) {
        state.hidden = hidden;
        if (root) { root.classList.toggle('stm-hidden', hidden); }
    }
    function checkAutoHide(inGame) {
        clearTimeout(hideTimer);
        if (inGame || !S.autoHide) { setHidden(false); return; }
        hideTimer = setTimeout(function () { setHidden(true); }, S.autoHideDelaySec * 1000);
    }
    function paint(d) {
        var counts = d.achievement_counts || {};
        var earned = Number(counts.unlocked) || 0;
        var total = Number(counts.total) || 0;
        var inGame = !!d.current_game_appid;
        var connected = d.connection_status === 'Connected' || d.connection_status === 'Offline';
        var name = inGame ? (d.current_game_name || S.defaultGameName) : S.defaultGameName;

        if (inGame && d.current_game_appid === state.appid && earned > state.earned) {
            showChange(earned - state.earned);
        }
        state.appid = d.current_game_appid || null;
        state.earned = earned;
        state.total = total;

        setText('game_title', name);
        var message;
        if (!inGame) {
            message = connected ? '' : 'Steam not connected';
        } else if (d.achievements_private) {
            message = S.privateText;
        } else if (!total) {
            message = S.noAchievementsText;
        } else {
            message = fmt(S.messageFormat, { earned: earned, total: total });
        }
        setText('ach_message', message);
        setText('level_info', d.steam_level != null ? fmt(S.levelFormat, { level: d.steam_level }) : '');
        setProgress(inGame ? earned : 0, inGame ? total : 0);
        setIcon(inGame ? [d.current_game_capsule_url, d.current_game_art_url, S.defaultGameIcon]
                       : [connected ? S.defaultGameIcon : S.notConnectedIcon]);
        show('perfect_badge', S.showPerfectBadge && inGame && total > 0 && earned >= total);
        checkAutoHide(inGame);
        painted = true;
        try { localStorage.setItem(CACHE_KEY, JSON.stringify(d)); } catch (e) { /* private mode */ }
    }
    function handle(d) {
        if (!d || typeof d !== 'object') { return; }
        var now = Date.now();
        /* First data paints at once; later changes get the short scale flash (at most every 2 s). */
        if (!S.enableAnimations || !root || !painted || now - lastPaint < 2000) {
            lastPaint = now;
            paint(d);
            return;
        }
        lastPaint = now;
        root.classList.add('stm-updating');
        setTimeout(function () { paint(d); root.classList.remove('stm-updating'); }, S.animationSec * 500);
    }
    function request() {
        if (typeof socket !== 'undefined' && socket && socket.emit) { socket.emit('get_steam_data'); }
    }

    try {
        var cached = JSON.parse(localStorage.getItem(CACHE_KEY) || 'null');
        if (cached) { paint(cached); }
    } catch (e) { /* no cache */ }
    show('ach_change', false);

    if (typeof socket !== 'undefined' && socket && socket.on) {
        socket.on('steam_data_update', handle);
        socket.on('steam_data_error', function () {
            if (root) { root.classList.add('stm-error'); setTimeout(function () { root.classList.remove('stm-error'); }, 3000); }
        });
        socket.on('connect', request);
    }
    request();
    if (S.updateIntervalSec > 0) { setInterval(request, S.updateIntervalSec * 1000); }
    document.addEventListener('visibilitychange', function () { if (!document.hidden) { request(); } });
    window.steamAchievementsDebug = { state: state, request: request, paint: paint };
})();
